unsigned int size = huffman_codes.size();
outfile.write(reinterpret_cast<const char*>(&size), sizeof(size));
for (const auto& pair : huffman_codes) {
    unsigned char ch = pair.first;
    const std::string& code = pair.second;
    unsigned char code_length = static_cast<unsigned char>(code.size());
    outfile.write(reinterpret_cast<const char*>(&ch), sizeof(ch));
    outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));
    for (size_t i = 0; i < code_length; ++i) {
        unsigned char bit = (code[i] == '1') ? 1 : 0;
        if (i % 8 == 0) {
            unsigned char byte = 0;
            for (size_t j = i; j < std::min(i + 8, code_length); ++j) {
                if (code[j] == '1') byte |= (1 << (7 - (j - i)));
            }
            outfile.write(reinterpret_cast<const char*>(&byte), sizeof(byte));
        }
    }
}

